import json
import numpy as np
from scipy.linalg import expm
from scipy.optimize import minimize_scalar
D=np.diag([0.,1.,2.35]); X=np.array([[0.,1.,.25],[1.,0.,.8],[.25,.8,0.]]); Y=np.array([[0.,-1j,.45j],[1j,0.,-.7j],[-.45j,.7j,0.]])
recs=json.load(open('data/calibration.json'))
def stat(e,s):
 t,a,b,ph,ta,tb=[e[k] for k in ['temperature','amplitude_a','amplitude_b','phase','time_a','time_b']]
 E=s*np.diag(D); p=np.exp(-E/t);p/=p.sum()
 U=expm(-1j*tb*(s*D+b*(np.cos(ph)*X+np.sin(ph)*Y)))@expm(-1j*ta*(s*D+a*X))
 de=E[:,None]-E[None,:] # j,i? row final j, col initial i
 q=np.abs(U)**2
 raw=[np.sum(p[None,:]*q*de**n) for n in (1,2,3)]
 return np.array([raw[0],raw[1]-raw[0]**2,raw[2]-3*raw[0]*raw[1]+2*raw[0]**3])
def resid(s):
 return np.array([(stat(r['input'],s)[r['input']['cumulant']-1]-r['value'])/r['sigma'] for r in recs])
res=minimize_scalar(lambda s: np.sum(resid(s)**2), bounds=(.8,1.2), method='bounded',options={'xatol':1e-14})
print(res.x,res.fun,res.fun/(len(recs)-1))
for r in recs[:4]: print(stat(r['input'],res.x),r['value'])
